import 'package:flutter/material.dart';

import '../game/cozy_adventure_game.dart';
import '../game/state/people_snapshot.dart';

/// Met-only journal. Every displayed fact comes from persisted learned IDs.
class PeopleJournalOverlay extends StatefulWidget {
  const PeopleJournalOverlay({required this.game, super.key});

  static const overlayKey = Key('people-journal-overlay');
  static const closeButtonKey = Key('people-journal-close-button');
  static const emptyKey = Key('people-journal-empty');

  static ValueKey<String> personKey(String npcId) =>
      ValueKey('people-journal-person-$npcId');

  final CozyAdventureGame game;

  @override
  State<PeopleJournalOverlay> createState() => _PeopleJournalOverlayState();
}

class _PeopleJournalOverlayState extends State<PeopleJournalOverlay> {
  String? _selectedNpcId;

  @override
  Widget build(BuildContext context) {
    return SizedBox.expand(
      child: ColoredBox(
        color: const Color(0xAA0D1712),
        child: SafeArea(
          minimum: const EdgeInsets.all(12),
          child: Center(
            child: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 920, maxHeight: 680),
              child: Material(
                key: PeopleJournalOverlay.overlayKey,
                color: Theme.of(context).colorScheme.surface,
                borderRadius: BorderRadius.circular(20),
                clipBehavior: Clip.antiAlias,
                child: ValueListenableBuilder<PeopleSnapshot>(
                  valueListenable: widget.game.peopleSnapshotListenable,
                  builder: (context, snapshot, child) {
                    final requested =
                        widget.game.activePeopleNpcIdListenable.value;
                    final selectedId = _resolveSelectedId(snapshot, requested);
                    final selected = _findPerson(snapshot, selectedId);
                    return LayoutBuilder(
                      builder: (context, constraints) {
                        final compact = constraints.maxWidth < 640;
                        return Column(
                          children: [
                            _Header(onClose: widget.game.closePeople),
                            const Divider(height: 1),
                            Expanded(
                              child: snapshot.people.isEmpty
                                  ? const Center(
                                      key: PeopleJournalOverlay.emptyKey,
                                      child: Padding(
                                        padding: EdgeInsets.all(24),
                                        child: Text(
                                          'Meet someone to add them to People.',
                                          textAlign: TextAlign.center,
                                        ),
                                      ),
                                    )
                                  : compact
                                  ? _compactBody(snapshot, selected)
                                  : _wideBody(snapshot, selected),
                            ),
                          ],
                        );
                      },
                    );
                  },
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _compactBody(PeopleSnapshot snapshot, PersonSnapshot? selected) {
    return Column(
      children: [
        if (snapshot.people.length > 1)
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
            child: DropdownButtonFormField<String>(
              initialValue: selected?.npcId,
              decoration: const InputDecoration(labelText: 'Person'),
              items: [
                for (final person in snapshot.people)
                  DropdownMenuItem(
                    value: person.npcId,
                    child: Text(person.displayName),
                  ),
              ],
              onChanged: (value) => setState(() => _selectedNpcId = value),
            ),
          ),
        Expanded(
          child: selected == null
              ? const SizedBox.shrink()
              : _PersonDetail(person: selected, compact: true),
        ),
      ],
    );
  }

  Widget _wideBody(PeopleSnapshot snapshot, PersonSnapshot? selected) {
    return Row(
      children: [
        SizedBox(
          width: 240,
          child: ListView.builder(
            padding: const EdgeInsets.all(12),
            itemCount: snapshot.people.length,
            itemBuilder: (context, index) {
              final person = snapshot.people[index];
              return ListTile(
                key: PeopleJournalOverlay.personKey(person.npcId),
                selected: selected?.npcId == person.npcId,
                title: Text(person.displayName),
                subtitle: Text(person.levelLabel ?? 'New acquaintance'),
                onTap: () => setState(() => _selectedNpcId = person.npcId),
              );
            },
          ),
        ),
        const VerticalDivider(width: 1),
        Expanded(
          child: selected == null
              ? const SizedBox.shrink()
              : _PersonDetail(person: selected, compact: false),
        ),
      ],
    );
  }

  String? _resolveSelectedId(PeopleSnapshot snapshot, String? requested) {
    final ids = snapshot.people.map((person) => person.npcId).toSet();
    if (_selectedNpcId != null && ids.contains(_selectedNpcId)) {
      return _selectedNpcId;
    }
    if (requested != null && ids.contains(requested)) {
      return requested;
    }
    return snapshot.people.firstOrNull?.npcId;
  }

  PersonSnapshot? _findPerson(PeopleSnapshot snapshot, String? id) {
    for (final person in snapshot.people) {
      if (person.npcId == id) {
        return person;
      }
    }
    return null;
  }
}

class _Header extends StatelessWidget {
  const _Header({required this.onClose});

  final VoidCallback onClose;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      child: Row(
        children: [
          Expanded(
            child: Text(
              'People',
              style: Theme.of(context).textTheme.headlineSmall,
            ),
          ),
          TextButton.icon(
            key: PeopleJournalOverlay.closeButtonKey,
            autofocus: true,
            onPressed: onClose,
            icon: const Icon(Icons.close),
            label: const Text('Close'),
          ),
        ],
      ),
    );
  }
}

class _PersonDetail extends StatelessWidget {
  const _PersonDetail({required this.person, required this.compact});

  final PersonSnapshot person;
  final bool compact;

  @override
  Widget build(BuildContext context) {
    final grouped = <String, List<PeopleFactSnapshot>>{};
    for (final fact in person.facts) {
      grouped.putIfAbsent(fact.category, () => []).add(fact);
    }
    return Semantics(
      container: true,
      label: 'Profile for ${person.displayName}',
      child: ListView(
        padding: const EdgeInsets.all(20),
        children: [
          Center(
            child: SizedBox.square(
              dimension: compact ? 160 : 240,
              child: Image.asset(
                person.portraitPath,
                fit: BoxFit.contain,
                filterQuality: FilterQuality.high,
                isAntiAlias: true,
                semanticLabel: 'Portrait of ${person.displayName}',
              ),
            ),
          ),
          const SizedBox(height: 12),
          Text(
            person.displayName,
            textAlign: TextAlign.center,
            style: Theme.of(context).textTheme.headlineSmall,
          ),
          Text(
            person.pronouns,
            textAlign: TextAlign.center,
            style: Theme.of(context).textTheme.bodyMedium,
          ),
          const SizedBox(height: 8),
          Text(
            person.levelLabel == null
                ? 'Relationship: ${person.affinity}/${person.levelOneAffinity}'
                : 'Relationship: ${person.levelLabel} (${person.affinity}/${person.levelOneAffinity})',
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: 20),
          if (grouped.isEmpty)
            const Text(
              'Keep talking to learn more.',
              textAlign: TextAlign.center,
            ),
          for (final entry in grouped.entries) ...[
            Text(entry.key, style: Theme.of(context).textTheme.titleMedium),
            const SizedBox(height: 6),
            for (final fact in entry.value)
              ListTile(
                contentPadding: EdgeInsets.zero,
                title: Text(fact.label),
                subtitle: Text(fact.description),
              ),
            const SizedBox(height: 8),
          ],
        ],
      ),
    );
  }
}
